package io.rift.cronos;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;
/** Executes on JVM with real org.json; fake RPC only, not provider/Android acceptance. */
public final class TransferDiscoveryTest {
 static final String OWNER="0x"+"a".repeat(40),OTHER="0x"+"b".repeat(40),CONTRACT="0x"+"c".repeat(40),HASH="0x"+"d".repeat(64),TX="0x"+"e".repeat(64);
 static String word(long n){return String.format(Locale.ROOT,"%064x",n);}
 static JSONObject log(String standard,boolean incoming,long id)throws Exception{JSONArray topics=standard.equals("ERC-721")?new JSONArray().put(DiscoveryPolicy.TRANSFER).put(DiscoveryPolicy.ownerTopic(incoming?OTHER:OWNER)).put(DiscoveryPolicy.ownerTopic(incoming?OWNER:OTHER)).put("0x"+word(id)):new JSONArray().put(DiscoveryPolicy.SINGLE).put(DiscoveryPolicy.ownerTopic(OTHER)).put(DiscoveryPolicy.ownerTopic(incoming?OTHER:OWNER)).put(DiscoveryPolicy.ownerTopic(incoming?OWNER:OTHER));return new JSONObject().put("address",CONTRACT).put("removed",false).put("blockNumber","0x64").put("blockHash",HASH).put("transactionHash",TX).put("logIndex","0x0").put("topics",topics).put("data",standard.equals("ERC-721")?"0x":"0x"+word(id)+word(7));}
 static final class Fake implements TransferDiscovery.Rpc {JSONArray incoming=new JSONArray(),outgoing=new JSONArray();List<JSONObject> filters=new ArrayList<>();int anchors=0;boolean reorg,wrongChain;
 public void requireCronos(){if(wrongChain)throw new IllegalStateException("Wrong chain");}
 public Object call(String method,JSONArray params)throws Exception{switch(method){case "eth_blockNumber":return "0x70";case "eth_getBlockByNumber":anchors++;return new JSONObject().put("number",params.getString(0)).put("hash",reorg&&anchors>1?"0x"+"f".repeat(64):HASH);case "eth_getLogs":filters.add(params.getJSONObject(0));return filters.size()==1?incoming:outgoing;default:throw new AssertionError("Unexpected method "+method);}}
 }
 @Test public void scoped721PageReturnsHintsNotBalances()throws Exception{Fake f=new Fake();f.incoming.put(log("ERC-721",true,42));JSONObject result=TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-721","100","10");assertEquals("109",result.getString("toBlock"));assertEquals("110",result.getString("nextFromBlock"));assertEquals("98",result.getString("suggestedRecheckFromBlock"));assertEquals("42",result.getJSONArray("candidates").getJSONObject(0).getString("tokenId"));assertFalse(result.has("balance"));assertEquals(2,f.anchors);assertEquals(CONTRACT,f.filters.get(0).getString("address"));assertEquals("0x64",f.filters.get(0).getString("fromBlock"));assertEquals(DiscoveryPolicy.ownerTopic(OWNER),f.filters.get(0).getJSONArray("topics").getString(2));assertEquals(DiscoveryPolicy.ownerTopic(OWNER),f.filters.get(1).getJSONArray("topics").getString(1));}
 @Test public void multiTokenFiltersKeepOperatorSlotAndClipAtHead()throws Exception{Fake f=new Fake();f.outgoing.put(log("ERC-1155",false,17));JSONObject result=TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-1155","100","2000");assertEquals("112",result.getString("toBlock"));assertTrue(result.isNull("nextFromBlock"));assertEquals("17",result.getJSONArray("candidates").getJSONObject(0).getString("tokenId"));assertEquals(4,f.filters.get(0).getJSONArray("topics").length());assertEquals(3,f.filters.get(1).getJSONArray("topics").length());assertTrue(f.filters.get(1).getJSONArray("topics").isNull(1));}
 @Test public void removedWrongOwnerOutOfRangeAndWrongContractFailClosed()throws Exception{for(String key:new String[]{"removed","address","blockNumber","owner"}){Fake f=new Fake();JSONObject event=log("ERC-721",true,1);if(key.equals("removed"))event.put(key,true);else if(key.equals("address"))event.put(key,OTHER);else if(key.equals("blockNumber"))event.put(key,"0x63");else event.getJSONArray("topics").put(2,DiscoveryPolicy.ownerTopic(OTHER));f.incoming.put(event);try{TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-721","100","10");fail(key+" accepted");}catch(Exception expected){}}}
 @Test public void anchorReorgAndWrongChainFailWithoutPartialPage()throws Exception{Fake f=new Fake();f.reorg=true;f.incoming.put(log("ERC-721",true,1));try{TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-721","100","10");fail("reorg accepted");}catch(java.io.IOException expected){}Fake wrong=new Fake();wrong.wrongChain=true;try{TransferDiscovery.scan(wrong,OWNER,CONTRACT,"ERC-721","100","10");fail("wrong chain accepted");}catch(IllegalStateException expected){}assertEquals(0,wrong.filters.size());}
 @Test public void selfTransfersDeduplicateAndConflictingDuplicatesReject()throws Exception{Fake f=new Fake();JSONObject self=log("ERC-721",true,1);self.getJSONArray("topics").put(1,DiscoveryPolicy.ownerTopic(OWNER));f.incoming.put(self);f.outgoing.put(new JSONObject(self.toString()));JSONObject r=TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-721","100","10");assertEquals(1,r.getInt("uniqueEvents"));assertEquals(1,r.getJSONArray("candidates").length());Fake conflict=new Fake();conflict.incoming.put(self);JSONObject altered=new JSONObject(self.toString());altered.getJSONArray("topics").put(3,"0x"+word(2));conflict.outgoing.put(altered);try{TransferDiscovery.scan(conflict,OWNER,CONTRACT,"ERC-721","100","10");fail("conflict accepted");}catch(java.io.IOException expected){}}
 @Test public void logAndCandidateCapsRejectRatherThanSilentlyTruncate()throws Exception{Fake f=new Fake();for(int i=0;i<513;i++)f.incoming.put(log("ERC-721",true,i));try{TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-721","100","10");fail("log overflow");}catch(java.io.IOException expected){}Fake c=new Fake();for(int i=0;i<201;i++)c.incoming.put(log("ERC-721",true,i).put("logIndex","0x"+Integer.toHexString(i)));try{TransferDiscovery.scan(c,OWNER,CONTRACT,"ERC-721","100","10");fail("candidate overflow");}catch(java.io.IOException expected){}}
 @Test public void recentWindowResolvesAgainstReadHeadOnlyAfterConsent()throws Exception{Fake f=new Fake();JSONObject r=TransferDiscovery.scan(f,OWNER,CONTRACT,"ERC-721","recent","10");assertEquals("103",r.getString("fromBlock"));assertEquals("112",r.getString("toBlock"));assertTrue(r.isNull("nextFromBlock"));assertEquals("0x67",f.filters.get(0).getString("fromBlock"));}

}
